//! Per-version block catalogues.
//!
//! A catalogue is plain data generated by the development tool
//! (`of-cli catalogue`) from a game install: the block names that exist in
//! that version, measured colours and what kind of block each one is.
//! Supporting another Minecraft version means adding another data file here.

use crate::model::{BlockState, Build};
use serde::{Deserialize, Serialize};
use std::collections::BTreeMap;
use std::sync::OnceLock;

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum Tier {
    /// Obtainable and placeable in a survival world.
    Survival,
    /// Exists as an item only in creative mode.
    Creative,
    /// Has no item at all (placed only by commands or the game itself).
    Technical,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct BlockInfo {
    /// Property names and the values seen for them in the game's block
    /// models. Not exhaustive: properties that do not change a block's
    /// appearance are missing, so this is not used to reject files.
    #[serde(default, skip_serializing_if = "BTreeMap::is_empty")]
    pub props: BTreeMap<String, Vec<String>>,
    /// Average colour of the top face, sRGB.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub top: Option<[u8; 3]>,
    /// Average colour of a side face, sRGB.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub side: Option<[u8; 3]>,
    /// Average opacity of the top face, 0 to 255.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub alpha: Option<u8>,
    /// How uneven the top face is: standard deviation of brightness, 0 to 1.
    /// Low values are smooth, flat-looking blocks.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub variation: Option<f32>,
    /// Fills its whole cell.
    #[serde(default)]
    pub full_cube: bool,
    /// Coloured by the biome it stands in (grass, leaves), so the measured
    /// colour is not what the player sees.
    #[serde(default, skip_serializing_if = "std::ops::Not::not")]
    pub tinted: bool,
    /// Falls when unsupported.
    #[serde(default)]
    pub gravity: bool,
    pub tier: Tier,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Catalogue {
    pub game_version: String,
    pub data_version: i32,
    /// Lowest and highest block positions a world of this version allows.
    pub min_y: i32,
    pub max_y: i32,
    pub blocks: BTreeMap<String, BlockInfo>,
}

pub const DYES: [&str; 16] = [
    "white", "orange", "magenta", "light_blue", "yellow", "lime", "pink", "gray", "light_gray", "cyan", "purple", "blue", "brown",
    "green", "red", "black",
];

impl Catalogue {
    pub fn knows(&self, state: &BlockState) -> bool {
        self.blocks.contains_key(&state.name)
    }
    /// Names of blocks in the build that this version does not have.
    pub fn unknown_in(&self, build: &Build) -> Vec<String> {
        let mut names: Vec<String> =
            build.histogram().into_iter().filter(|(s, _)| !self.knows(s)).map(|(s, _)| s.name).collect();
        names.sort();
        names.dedup();
        names
    }
    pub fn concretes(&self) -> Vec<String> {
        DYES.iter().map(|d| format!("minecraft:{d}_concrete")).filter(|n| self.blocks.contains_key(n)).collect()
    }
    pub fn stained_glass(&self) -> Vec<String> {
        DYES.iter().map(|d| format!("minecraft:{d}_stained_glass")).filter(|n| self.blocks.contains_key(n)).collect()
    }
    /// Opaque, full-cube blocks with a measured colour: the candidates for
    /// coloured surfaces. `survival_only` leaves out creative-only blocks,
    /// and `allow_gravity` decides whether falling blocks may be used.
    pub fn solid_colour_blocks(&self, survival_only: bool, allow_gravity: bool) -> Vec<(&str, &BlockInfo)> {
        self.blocks
            .iter()
            .filter(|(_, b)| b.full_cube && !b.tinted && b.top.is_some() && b.alpha.unwrap_or(255) == 255)
            .filter(|(_, b)| b.tier != Tier::Technical && (!survival_only || b.tier == Tier::Survival))
            .filter(|(_, b)| allow_gravity || !b.gravity)
            .map(|(n, b)| (n.as_str(), b))
            .collect()
    }
}

/// Blocks that fall when nothing is beneath them.
pub fn is_gravity(name: &str) -> bool {
    let n = name.strip_prefix("minecraft:").unwrap_or(name);
    n.ends_with("_concrete_powder")
        || matches!(
            n,
            "sand" | "red_sand" | "gravel" | "anvil" | "chipped_anvil" | "damaged_anvil" | "dragon_egg" | "scaffolding"
                | "pointed_dripstone" | "suspicious_sand" | "suspicious_gravel"
        )
}

/// Classify by name. Kept as code (not measured) because the game's files
/// do not state it; reviewed for 26.1.2.
pub fn tier_of(name: &str) -> Tier {
    let n = name.strip_prefix("minecraft:").unwrap_or(name);
    const TECHNICAL: [&str; 34] = [
        "air", "cave_air", "void_air", "water", "lava", "fire", "soul_fire", "nether_portal", "end_portal", "end_gateway",
        "piston_head", "moving_piston", "bubble_column", "frosted_ice", "tall_seagrass", "kelp_plant", "bamboo_sapling",
        "redstone_wire", "tripwire", "powder_snow", "cave_vines", "cave_vines_plant", "weeping_vines_plant",
        "twisting_vines_plant", "big_dripleaf_stem", "sweet_berry_bush", "cocoa", "attached_melon_stem",
        "attached_pumpkin_stem", "melon_stem", "pumpkin_stem", "torchflower_crop", "pitcher_crop", "test_instance_block",
    ];
    const CREATIVE: [&str; 21] = [
        "bedrock", "barrier", "light", "command_block", "chain_command_block", "repeating_command_block", "structure_block",
        "structure_void", "jigsaw", "end_portal_frame", "spawner", "trial_spawner", "vault", "reinforced_deepslate",
        "budding_amethyst", "petrified_oak_slab", "player_head", "debug_stick", "test_block", "farmland", "dirt_path",
    ];
    if TECHNICAL.contains(&n)
        || n.starts_with("potted_")
        || n.ends_with("_wall_sign")
        || n.ends_with("_wall_hanging_sign")
        || n.ends_with("_wall_banner")
        || n.ends_with("_wall_head")
        || n.ends_with("_wall_skull")
        || n.ends_with("wall_torch")
        || n.ends_with("_wall_fan")
        || n.ends_with("_cauldron") && n != "cauldron"
        || n.ends_with("_candle_cake")
        || n == "candle_cake"
        || matches!(n, "wheat" | "carrots" | "potatoes" | "beetroots" | "player_wall_head")
    {
        Tier::Technical
    } else if CREATIVE.contains(&n) || n.starts_with("infested_") {
        Tier::Creative
    } else {
        Tier::Survival
    }
}

/// Versions with a catalogue built in, newest first.
pub const VERSIONS: [&str; 1] = ["26.1.2"];

pub fn for_version(game_version: &str) -> Option<&'static Catalogue> {
    static JAVA_26_1_2: OnceLock<Catalogue> = OnceLock::new();
    match game_version {
        "26.1.2" => Some(JAVA_26_1_2.get_or_init(|| {
            serde_json::from_str(include_str!("../../../assets/catalogue/java-26.1.2.json")).expect("built-in catalogue is valid")
        })),
        _ => None,
    }
}

pub fn default() -> &'static Catalogue {
    for_version(VERSIONS[0]).expect("the default version has a catalogue")
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_built_in_catalogue_has_what_the_app_relies_on() {
        let c = default();
        assert_eq!(c.game_version, "26.1.2");
        assert!(c.data_version > 4000, "data version {}", c.data_version);
        assert_eq!((c.min_y, c.max_y), (-64, 319));
        assert_eq!(c.concretes().len(), 16);
        assert_eq!(c.stained_glass().len(), 16);
        assert!(c.blocks.len() > 900, "{} blocks", c.blocks.len());
        for name in c.concretes() {
            let b = &c.blocks[&name];
            assert!(b.full_cube && b.top.is_some() && !b.gravity && b.tier == Tier::Survival, "{name}");
        }
        assert!(c.blocks["minecraft:white_concrete_powder"].gravity);
        assert!(c.blocks["minecraft:sand"].gravity);
        assert_eq!(c.blocks["minecraft:bedrock"].tier, Tier::Creative);
        assert!(c.blocks["minecraft:blue_stained_glass"].alpha.unwrap() < 255);
        // Survival-safe, non-falling candidates exclude powder and bedrock.
        let safe: Vec<&str> = c.solid_colour_blocks(true, false).into_iter().map(|(n, _)| n).collect();
        assert!(safe.contains(&"minecraft:blue_concrete"));
        assert!(!safe.contains(&"minecraft:blue_concrete_powder"));
        assert!(!safe.contains(&"minecraft:bedrock"));
        assert!(!safe.contains(&"minecraft:blue_stained_glass"));
    }

    #[test]
    fn unknown_blocks_are_found() {
        let mut build = Build::new();
        let stone = build.palette.intern(BlockState::new("stone"));
        let odd = build.palette.intern(BlockState::new("somemod:shiny"));
        let mut region = crate::model::Region::new("r", [0; 3], [2, 1, 1]);
        let mut cells = crate::model::Volume::new();
        cells.set([0, 0, 0], stone);
        cells.set([1, 0, 0], odd);
        region.cells = std::sync::Arc::new(cells);
        build.regions.push(region);
        assert_eq!(default().unknown_in(&build), vec!["somemod:shiny".to_string()]);
    }
}
